 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(r for r, row in enumerate(grid) if all(v == 2 for v in row))
    out = [row[:] for row in grid]
    # All 4s on either side of the horizontal divider shift one row toward it.
    # Simultaneously moving original cells reproduces the one-row shift demo;
    # the colored divider and zeros are otherwise preserved.
    for r in range(h):
        if r == divider:
            continue
        for c in range(w):
            if grid[r][c] == 4:
                out[r][c] = 0
                nr = r + (1 if r < divider else -1)
                if 0 <= nr < h and nr != divider:
                    out[nr][c] = 4
    return out

